// === Tab: mySketch ===
let img;
let attForce = 0.03;
let repForce = 0.05;

let particles = [];
let numParticle = 10000;

function preload() {
	img = loadImage('https://lf9-survey.bytetos.com/obj/web.business.image/202201025d0dabbaed2554fc4f389142');
}

function setup() {
	let canvasSize = max(windowWidth, windowHeight);
	createCanvas(1112, 834);
	img.resize(height, 0);
	strokeWeight(5);
	background(0);

	for (let i = 0; i < numParticle; i++) {
		particles.push(new Particle(random(width), random(height)));
	}
}

function draw() {
	translate(80, -40);
	fill(0, 20);
	noStroke();
	rect(0, 0, width, height);

	for (let p of particles) {
		p.move();
		p.display();
	}
}

class Particle {
	constructor(_x, _y) {
		this.pos = createVector(_x, _y);
		this.target = this.pos.copy();
		this.vel = createVector(0, 0);
		this.acc = createVector(0, 0);
		this.color = img.get(_x, _y);
	}

	move() {
		let attraction = p5.Vector.sub(this.target, this.pos);
		attraction.mult(attForce);
		let tmpForce = p5.Vector.sub(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), this.pos).limit(30);
		let repulsion = tmpForce.copy().normalize().mult(-30).sub(tmpForce);
		repulsion.mult(repForce);

		this.acc = p5.Vector.add(attraction, repulsion);
		this.vel.mult(0.97);
		this.vel.add(this.acc);
		this.vel.limit(3);
		this.pos.add(this.vel);
	}

	display() {
		stroke(this.color);
		point(this.pos.x, this.pos.y);
	}

}

